INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-10341','GHBC-REQ-010341','GS 1207:2018',11,'11.23','11.23.3','GHBC-C-002990','Interior exit stairways and ramps shall terminate at an exit discharge or a public way.','fire',NULL,NULL,NULL,NULL,'["A combination of interior exit stairways, interior exit ramps and exit passageways, constructed in accordance with Clauses 11.23.2, 11.23.3.1 and 11.24, respectively, and forming a continuous protected enclosure, shall be permitted to extend an interior exit stairway or ramp to the exit discharge or a public way."]','[]','[]',0.9,'extracted','VERIFIED','2018','2ecc11935b54cc41010845cb06d211c1593e65413aaceac222450fa36eefb7a0','2026-08-15 13:56:13'),
('rowid-10342','GHBC-REQ-010342','GS 1207:2018',11,'11.23','11.23.3','GHBC-C-002990','EXCEPTIONS: A combination of interior exit stairways, interior exit ramps and exit passageways, constructed in accordance with Clauses 11.23.2, 11.23.3.1 and 11.24, respectively, and forming a continuous protected enclosure, shall be permitted to extend an interior exit stairway or ramp to the exit discharge or a public way.','fire',NULL,NULL,NULL,NULL,'["A combination of interior exit stairways, interior exit ramps and exit passageways, constructed in accordance with Clauses 11.23.2, 11.23.3.1 and 11.24, respectively, and forming a continuous protected enclosure, shall be permitted to extend an interior exit stairway or ramp to the exit discharge or a public way."]','[]','[]',0.9,'extracted','VERIFIED','2018','21d1202e08129733b59f85ac409ad3aedac2aaca496092ff22e5c7ec9665e388','2026-08-15 13:56:13'),
('rowid-10343','GHBC-REQ-010343','GS 1207:2018',11,'11.23','11.23.3.1','GHBC-C-002991','Where interior exit stairways and ramps are extended to an exit discharge or a public way by an exit passageway, the interior exit stairway and ramp shall be separated from the exit passageway by a fire barrier constructed in','fire',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','d6d75b17353573d88ff7a7d40262fd0e9c3b18e305bdbcb29bc91b0b8775a4a3','2026-08-15 13:56:13'),
('rowid-10344','GHBC-REQ-010344','GS 1207:2018',11,'11.23','11.23.3.1','GHBC-C-002991','accordance with Clause 8.7 or a horizontal assembly constructed in accordance with Clause 8.11, or both.','informational',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','364f9d266a30677175cf75c1aa07ab8df98537ebd9850a54367e6b352d723d98','2026-08-15 13:56:13'),
('rowid-10345','GHBC-REQ-010345','GS 1207:2018',11,'11.23','11.23.3.1','GHBC-C-002991','The fire-resistance rating shall be not less than that required for the interior exit stairway and ramp.','fire',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','c90afedde00c19b21c8c72412258b9e97deb7369c3ca3cb3851df231eb3654b5','2026-08-15 13:56:13'),
