INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-10891','GHBC-REQ-010891','GS 1207:2018',11,'11.29','11.29.17.1','GHBC-C-003107','Bleachers, grandstands and folding and telescopic seating shall not be required to have perimeter guards where the seating is located adjacent to a wall and the space between the wall and the seating is less than 102 mm (4 inches).','prohibited',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":102,"unit":null,"operator":"less than","context":"n the wall and the seating is less than 102 mm (4 inches)."},{"parameter":"measurement","value":102,"unit":"mm","operator":null,"context":" and the seating is less than 102 mm (4 inches)."},{"parameter":"measurement","value":4,"unit":"in","operator":null,"context":" seating is less than 102 mm (4 inches)."}]','[]',0.93,'requires_review','DRAFT','2018','52126da97bacf58505005bfdf7f1126da997ece5665fc7d25af7ead33282402a','2026-08-15 13:56:13'),
('rowid-10892','GHBC-REQ-010892','GS 1207:2018',11,'11.29','11.29.17.2','GHBC-C-003108','Cross aisles located more than 762 mm (30 inches) above the floor or grade below shall have guards in accordance with Clause 11.15.','mandatory',NULL,NULL,NULL,NULL,'["Where the backs of seats on the front of the cross aisle project 610 mm (24 inches) or more above the adjacent floor of the aisle, a guard need not be provided."]','[{"parameter":"comparison","value":762,"unit":null,"operator":"more than","context":"Cross aisles located more than 762 mm (30 inches) above the floo"},{"parameter":"measurement","value":762,"unit":"mm","operator":null,"context":"ross aisles located more than 762 mm (30 inches) above the floor o"},{"parameter":"measurement","value":30,"unit":"in","operator":null,"context":"les located more than 762 mm (30 inches) above the floor or grade"}]','[]',0.93,'extracted','VERIFIED','2018','228914d40d1636b69b6e5296bf3bf2ded9a1d053d35f9dd9dcfda8fa6b87fb6e','2026-08-15 13:56:13'),
('rowid-10893','GHBC-REQ-010893','GS 1207:2018',11,'11.29','11.29.17.2','GHBC-C-003108','Where an elevation change of 762 mm (30 inches) or less occurs between a cross aisle and the adjacent floor or grade below, guards not less than 660 mm (26 inches) above the aisle floor shall be provided.','conditional',NULL,NULL,NULL,NULL,'["Where the backs of seats on the front of the cross aisle project 610 mm (24 inches) or more above the adjacent floor of the aisle, a guard need not be provided."]','[{"parameter":"comparison","value":660,"unit":null,"operator":"not less than","context":" floor or grade below, guards not less than 660 mm (26 inches) above the aisl"},{"parameter":"measurement","value":762,"unit":"mm","operator":null,"context":"Where an elevation change of 762 mm (30 inches) or less occurs be"},{"parameter":"measurement","value":30,"unit":"in","operator":null,"context":"n elevation change of 762 mm (30 inches) or less occurs between a"},{"parameter":"measurement","value":660,"unit":"mm","operator":null,"context":"e below, guards not less than 660 mm (26 inches) above the aisle f"},{"parameter":"measurement","value":26,"unit":"in","operator":null,"context":" guards not less than 660 mm (26 inches) above the aisle floor sh"}]','[]',0.93,'extracted','VERIFIED','2018','318de44ea9093e8424a515ef28d3c898f188cc8dce315f926196ce6eb6a4be0e','2026-08-15 13:56:13'),
('rowid-10894','GHBC-REQ-010894','GS 1207:2018',11,'11.29','11.29.17.2','GHBC-C-003108','11.29.17.3 Sightline-constrained guard heights.','dimensional',NULL,NULL,NULL,NULL,'["Where the backs of seats on the front of the cross aisle project 610 mm (24 inches) or more above the adjacent floor of the aisle, a guard need not be provided."]','[{"parameter":"measurement","value":17.3,"unit":"s","operator":null,"context":"11.29.17.3 Sightline-constrained guard hei"}]','[]',0.93,'requires_review','DRAFT','2018','247dee97d015b5ada4d0a72856b56af46310f2edb776e8084e134e5378d4cadc','2026-08-15 13:56:13'),
('rowid-10895','GHBC-REQ-010895','GS 1207:2018',11,'11.29','11.29.17.2','GHBC-C-003108','Unless subject to the requirements of Clause 11.29.17.4, a fascia or railing system in accordance with the guard requirements of Clause 11.15 and having a minimum height of 660 mm (26 inches) shall be provided where the floor or footboard elevation is more than 762 mm (30 inches) above the floor or grade below and the fascia or railing would otherwise interfere with the sightlines of immediately adjacent seating.','conditional',NULL,NULL,NULL,NULL,'["Where the backs of seats on the front of the cross aisle project 610 mm (24 inches) or more above the adjacent floor of the aisle, a guard need not be provided."]','[{"parameter":"comparison","value":762,"unit":null,"operator":"more than","context":"oor or footboard elevation is more than 762 mm (30 inches) above the floo"},{"parameter":"measurement","value":660,"unit":"mm","operator":null,"context":"nd having a minimum height of 660 mm (26 inches) shall be provided"},{"parameter":"measurement","value":26,"unit":"in","operator":null,"context":"g a minimum height of 660 mm (26 inches) shall be provided where "},{"parameter":"measurement","value":762,"unit":"mm","operator":null,"context":"tboard elevation is more than 762 mm (30 inches) above the floor o"},{"parameter":"measurement","value":30,"unit":"in","operator":null,"context":"levation is more than 762 mm (30 inches) above the floor or grade"}]','[]',0.93,'extracted','VERIFIED','2018','ce4eafb40530602d6dc8762d26ca5cf2df138b0ad1f653b81b429b414baa0dba','2026-08-15 13:56:13'),
('rowid-10896','GHBC-REQ-010896','GS 1207:2018',11,'11.29','11.29.17.2','GHBC-C-003108','EXCEPTIONS: Where the backs of seats on the front of the cross aisle project 610 mm (24 inches) or more above the adjacent floor of the aisle, a guard need not be provided.','conditional',NULL,NULL,NULL,NULL,'["Where the backs of seats on the front of the cross aisle project 610 mm (24 inches) or more above the adjacent floor of the aisle, a guard need not be provided."]','[{"parameter":"measurement","value":610,"unit":"mm","operator":null,"context":"nt of the cross aisle project 610 mm (24 inches) or more above the"},{"parameter":"measurement","value":24,"unit":"in","operator":null,"context":"e cross aisle project 610 mm (24 inches) or more above the adjace"}]','[]',0.93,'extracted','VERIFIED','2018','6915f6e4c1c2f8c89d2d4258fb764d41295da1a7fa4c269be6c7d9ea0107f0ba','2026-08-15 13:56:13'),
