INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-12831','GHBC-REQ-012831','GS 1207:2018',17,NULL,NULL,'GHBC-C-003613','These are to be used in calculating loads for local areas but not for calculating the load on entire structural elements such as roof and walls.','structural',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','018befeeb664d37e4311d37ebdc2bb018ee06115d8c1fecec043d77c5dfe2be3','2026-08-15 13:56:13'),
('rowid-12832','GHBC-REQ-012832','GS 1207:2018',17,NULL,NULL,'GHBC-C-003613','In such locations, the construction must be adequate to resist the local forces (additional nailing, anchoring etc.).','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','7a0b413e6286329bf84cd4cd5e99ea0950b8a32a7ab6fe00100a3eac3682550d','2026-08-15 13:56:13'),
('rowid-12833','GHBC-REQ-012833','GS 1207:2018',17,NULL,NULL,'GHBC-C-003613','Furthermore, it should be noted that these local forces can act in a shaking manner and result in fatigue failures.','informational',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','5da7b7dca6e75234e6f5cd55a9511f17d94cd85b171556a0668820c2b6bff6f1','2026-08-15 13:56:13'),
