('rowid-13477','GHBC-REQ-013477','GS 1207:2018',17,NULL,'17.10.8.6.2','GHBC-C-003669','bottom bars bent up.','informational',NULL,NULL,NULL,NULL,'[]','[]','["BS 8110","is 600"]',0.9,'extracted','VERIFIED','2018','e20ac1eb3b849ffdc4f90453505d72351e6dd29a08d2f1892a4f476b3d4aaf1d','2026-08-15 13:56:13'),
('rowid-13478','GHBC-REQ-013478','GS 1207:2018',17,NULL,'17.10.8.6.2','GHBC-C-003669','(iii) Development length of beam reinforcement shall be computed beginning at a distance of 10  from the near face column.','structural',NULL,NULL,NULL,NULL,'[]','[]','["BS 8110","is 600"]',0.9,'extracted','VERIFIED','2018','34fe8164127758c18e58c56461083eeaaaf828b74e4d0862e3392e2c9d0fa5f1','2026-08-15 13:56:13'),
