INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-14691','GHBC-REQ-014691','GS 1207:2018',19,'19.4','19.4.2.5','GHBC-C-003905','Where fabrication of structural, load-bearing or lateral load-resisting members or assemblies is being conducted on the premises of a fabricator‘s shop, special inspections of the fabricated items shall be performed during fabrication, except where the fabricator has been approved to perform work without special inspections in accordance with Clause 19.4.2.5.1.','structural',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','7438ee50aea426fdba389511a5c8c8b81825f67d535e7b702e64d8471c61fd38','2026-08-15 13:56:13'),
