('rowid-15259','GHBC-REQ-015259','GS 1207:2018',20,'20.6','20.6.4','GHBC-C-004017','Batching boxes for volume batching shall be filled without any tamping, ramming or consolidating of material other than that occurring naturally.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','dfd2001e8153c39d4f8723195cbb91a866750496c95cf5a89a664aad07e197a5','2026-08-15 13:56:13'),
('rowid-15260','GHBC-REQ-015260','GS 1207:2018',20,'20.6','20.6.4','GHBC-C-004017','Boxes shall be screened off level with their topmost edges.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','b9379a24576cb29b8b4cad099740b192b8f17ccaeb9bed84911e49bf9c9036e2','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15261','GHBC-REQ-015261','GS 1207:2018',20,'20.6','20.6.4','GHBC-C-004017','Any adjustment to the volume shall be made by supplementary boxes of a suitable size being used.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','6d750af1cb7d22d5a9cba9eb33ffe69ccb89bb284766ba2eaf8d926a44a5c22f','2026-08-15 13:56:13'),
