INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15271','GHBC-REQ-015271','GS 1207:2018',20,'20.7','20.7.2','GHBC-C-004019','The volume of mixed material by batch shall not exceed the volume recommended by the manufacturer of the mixer.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','2e1bedeed176b72d679be3e55477f349740288f70b59e110165976b4249c9e03','2026-08-15 13:56:13'),
('rowid-15272','GHBC-REQ-015272','GS 1207:2018',20,'20.7','20.7.3','GHBC-C-004020','The nominal drum or pan capacity of the mixer shall not be exceeded.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','eacd821a09d520262218bfd5a0f737f31d2963f877cfbfbfe9382acbbf4a3a92','2026-08-15 13:56:13'),
('rowid-15273','GHBC-REQ-015273','GS 1207:2018',20,'20.7','20.7.3','GHBC-C-004020','The turning speed and the mixing time shall be as recommended by the manufacturer, but in addition, when water is the last ingredient to be added, mixing shall continue for at least one minute after all the water has been added to the drum or pan.','conditional',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','1e68f0b4dad1f49379eebeb36d0eff9d52b4d40408e9471cc5ca27f90de179f5','2026-08-15 13:56:13'),
('rowid-15274','GHBC-REQ-015274','GS 1207:2018',20,'20.7','20.7.3','GHBC-C-004020','The water to be added to the mix shall be reduced by the amount of free water contained in the coarse and fine aggregates.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','406d042f2badb993dd88c49c00cca52eec8ce954eaf562a054071b2001bf94e5','2026-08-15 13:56:13'),
('rowid-15275','GHBC-REQ-015275','GS 1207:2018',20,'20.7','20.7.3','GHBC-C-004020','This amount shall be determined by the Owner or Owner‘s Authorised Agent by a method approved by the Head of works immediately before mixing begins each day and thereafter at least once per hour during concreting and for delivery of aggregates during concreting.','approval',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','6af90f75b8de3e01b05da789295b6b7a972cda8b80e91b544967a211fdd34c5e','2026-08-15 13:56:13'),
('rowid-15276','GHBC-REQ-015276','GS 1207:2018',20,'20.7','20.7.3','GHBC-C-004020','When the correct quantity of water, determined as set out in the Specification, has been added to the mix, no further water shall be added, either during mixing or subsequently.','conditional',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','ec51c84a77edad04cb27f838b7a7691536f6bd967b818bb23a9a2f3dd6f3db7d','2026-08-15 13:56:13'),
('rowid-15277','GHBC-REQ-015277','GS 1207:2018',20,'20.7','20.7.3','GHBC-C-004020','After mixing for the required time, each batch shall be discharged completely from the mixer before any materials for the succeeding batch are introduced.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','996e26aa2b50e85845bbfbbcda0c21c938d68778333d77d280e1ed2ee24071f0','2026-08-15 13:56:13'),
('rowid-15278','GHBC-REQ-015278','GS 1207:2018',20,'20.7','20.7.3','GHBC-C-004020','Mixers that have been out of use for more than 30 minutes shall be thoroughly cleaned before any fresh concrete is mixed and thereafter the first batch of concrete through the mixers shall contain only half the normal quantity of coarse aggregate.','material',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":30,"unit":null,"operator":"more than","context":"that have been out of use for more than 30 minutes shall be thoroughly c"},{"parameter":"measurement","value":30,"unit":"m","operator":null,"context":"been out of use for more than 30 minutes shall be thoroughly cle"}]','[]',0.93,'extracted','VERIFIED','2018','eb98a9b215c245b52f65ecc4d33cd4b6615ea0a4e5ba1fbb4c6a84ca139e6686','2026-08-15 13:56:13'),
('rowid-15279','GHBC-REQ-015279','GS 1207:2018',20,'20.7','20.7.3','GHBC-C-004020','This batch shall be mixed for one minute longer than the time applicable to a normal batch.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','ca209d2eb191c174c5adf88492f8504314a3af4e663d6bd7e4ad634c37fbe308','2026-08-15 13:56:13'),
('rowid-15280','GHBC-REQ-015280','GS 1207:2018',20,'20.7','20.7.4','GHBC-C-004021','The blades of pan mixers shall be maintained within the tolerances specified by the manufacturer of the mixer and the blades shall be replaced when it is no longer possible to maintain the tolerances by adjustment.','conditional',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','cd84d8f689cb7d36283685a911b905e4cc0e2a1b160b32ba2084378c7d7af6a9','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15281','GHBC-REQ-015281','GS 1207:2018',20,'20.7','20.7.4','GHBC-C-004021','Mixers shall be cleaned out before changing to another type of cement.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','dd83c66568a4bac8964e697dff2e407cc1a33e5daaf5d0d74808e3797911de9b','2026-08-15 13:56:13'),
('rowid-15282','GHBC-REQ-015282','GS 1207:2018',20,'20.7','20.7.4','GHBC-C-004021','If the mixer has stopped running for a period in excess of 30 minutes, it shall be thoroughly cleaned out.','conditional',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":30,"unit":"m","operator":null,"context":"ing for a period in excess of 30 minutes, it shall be thoroughly"}]','[]',0.93,'extracted','VERIFIED','2018','6cc653607c676c7e5c0bfd535e8e581f255ef5c9a89e10f1b25dec9fce9a2f81','2026-08-15 13:56:13'),
('rowid-15283','GHBC-REQ-015283','GS 1207:2018',20,'20.7','20.7.4','GHBC-C-004021','Before any concrete is mixed, the inner surfaces of the mixer shall be cleaned and all hardened concrete shall be removed.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','7c92e1b004dca1801dbf1cc6daf7c9dfe4c1e89b8d09757238df617659e4793c','2026-08-15 13:56:13'),
('rowid-15284','GHBC-REQ-015284','GS 1207:2018',20,'20.7','20.7.5','GHBC-C-004022','When clauses are cast where it is important for the casting to continue without interruption, a standby mixer shall be held in readiness to run on 15 minutes notice should the stock mixer break down.','conditional',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":15,"unit":"m","operator":null,"context":"e held in readiness to run on 15 minutes notice should the stock"}]','[]',0.93,'extracted','VERIFIED','2018','eb3ffd4edb8db9498566de93d6b9fdc8c9e46729b15f9889544981c1a967efab','2026-08-15 13:56:13'),
('rowid-15285','GHBC-REQ-015285','GS 1207:2018',20,'20.7','20.7.6','GHBC-C-004023','If the Owner or Owner‘s Authorised Agent proposes to use ready mixed concrete he shall submit to the Head of works for his approval full details and test results of the concrete mixes.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','6da348a80b11cf7e1a40716167334add2a546f71add20acb3816600c23b2af38','2026-08-15 13:56:13'),
('rowid-15286','GHBC-REQ-015286','GS 1207:2018',20,'20.7','20.7.6','GHBC-C-004023','The Head of works may approve the use of ready mixed concrete provided that:','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','7c5db7b882819d212ebd3b491fe125cee8c5a051ca390b097a34bf183787eb4a','2026-08-15 13:56:13'),
('rowid-15287','GHBC-REQ-015287','GS 1207:2018',20,'20.7','20.7.6','GHBC-C-004023','i. the proposed mixes, the material to be used and the method of storage and mixing comply with the requirements of the Specification; and ii. adequate control is exercised during mixing.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','ad6a90dfd008db3970326bedf6fc2c6f3c92b746b7c8f9cd30e22a519112768a','2026-08-15 13:56:13'),
('rowid-15288','GHBC-REQ-015288','GS 1207:2018',20,'20.7','20.7.6','GHBC-C-004023','Approval for the use of ready mixed concrete shall be withdrawn if the Head of works is not satisfied with the control of the materials being used and control during mixing.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','b7840c8e1a91d8ed57ab7fe9bc18d9b3a4df2a2acf60eba4361f282d8cb1196c','2026-08-15 13:56:13'),
('rowid-15289','GHBC-REQ-015289','GS 1207:2018',20,'20.7','20.7.7','GHBC-C-004024','Concrete for structural purposes shall not be mixed by hand.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','be1542f4949b5d16cd3da1596133b5babc44d23fb3a5208db2041edcc578d7b0','2026-08-15 13:56:13'),
('rowid-15290','GHBC-REQ-015290','GS 1207:2018',20,'20.7','20.7.7','GHBC-C-004024','Where non-structural concrete is required, hand mixing may be carried out subject to the approval of the Head of works.','structural',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','18cecf3226c45c4c6da1990eb8a6cd5a32833431fa7b03b0d49acc62507c46f2','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15291','GHBC-REQ-015291','GS 1207:2018',20,'20.7','20.7.7','GHBC-C-004024','The mixing shall be done on a hard impermeable surface.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','caed684e3a80edf61404984aa2b72d81f1a69fdcefd81e9c74c507e6d8d1a23c','2026-08-15 13:56:13'),
('rowid-15292','GHBC-REQ-015292','GS 1207:2018',20,'20.7','20.7.7','GHBC-C-004024','The materials shall be turned over not less than three times dry, water shall then be sprayed on and the materials again turned over not less than three times in a wet condition and worked together until a mixture of uniform consistency is obtained.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','08dd4dbae48e20b5dee8ff0da2a9870e8905978f7e618c284500ecc716be2bc6','2026-08-15 13:56:13'),
('rowid-15293','GHBC-REQ-015293','GS 1207:2018',20,'20.7','20.7.7','GHBC-C-004024','For hand mixed concrete the specified quantities of cement shall be increased by 10% and not more than 0.5 m3 shall be mixed at one time.','material',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":0.5,"unit":null,"operator":"not more than","context":"shall be increased by 10% and not more than 0.5 m3 shall be mixed at one time"},{"parameter":"measurement","value":10,"unit":"%","operator":null,"context":" cement shall be increased by 10% and not more than 0.5 m3 shal"},{"parameter":"measurement","value":0.5,"unit":"m3","operator":null,"context":"ased by 10% and not more than 0.5 m3 shall be mixed at one time."}]','[]',0.93,'extracted','VERIFIED','2018','a3189b2e64329bf39644baaf2c4413edd108a6c61097842fa9036f267a202d48','2026-08-15 13:56:13'),
('rowid-15294','GHBC-REQ-015294','GS 1207:2018',20,'20.7','20.7.7','GHBC-C-004024','During windy weather efficient precautions shall be taken to prevent cement from being blown away during the process of gauging and mixing.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','6b766762a1b5a43f31a48d42452feb65ced7c2e7a34cb0f8885e60445502137c','2026-08-15 13:56:13'),
('rowid-15295','GHBC-REQ-015295','GS 1207:2018',20,'20.8',NULL,'GHBC-C-004025','The concrete shall be discharged from the mixer and transported to the Works by means that shall prevent contamination, segregation or loss of ingredients and, which shall ensure that the concrete is of the required workability at the point and time of placing.','material',NULL,NULL,NULL,NULL,'[]','[]','["EN 206"]',0.9,'extracted','VERIFIED','2018','6bf782debec6736e0ba66b7b7ca77e4263070cb499153fc1bf6112828b9cc5e5','2026-08-15 13:56:13'),
('rowid-15296','GHBC-REQ-015296','GS 1207:2018',20,'20.8',NULL,'GHBC-C-004025','The loss of slump between discharge from the mixer and placing shall not exceed 25 mm.','prohibited',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":25,"unit":"mm","operator":null,"context":" and placing shall not exceed 25 mm."}]','["EN 206"]',0.93,'requires_review','DRAFT','2018','e323a12ec02848a948eee10d0c02ba9fc83379d92fd3560eeecff0fad669c150','2026-08-15 13:56:13'),
('rowid-15297','GHBC-REQ-015297','GS 1207:2018',20,'20.8',NULL,'GHBC-C-004025','The time elapsing between mixing and placing a batch of concrete shall be as short as practicable and in no case longer than will permit completion of placing and compaction before the onset of initial set.','material',NULL,NULL,NULL,NULL,'[]','[]','["EN 206"]',0.9,'extracted','VERIFIED','2018','9fcf974c8a551f5deb75ddd742cd477de3d6b6337e72e2bdffe18e2c3793266d','2026-08-15 13:56:13'),
('rowid-15298','GHBC-REQ-015298','GS 1207:2018',20,'20.8',NULL,'GHBC-C-004025','If the placing of any batch of concrete is delayed beyond this period, the concrete shall not be placed in the Works.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','["EN 206"]',0.9,'requires_review','DRAFT','2018','472546af8c159570f1370e8def3d993c7253f19e5f07602191b9dfd7719e8dcc','2026-08-15 13:56:13'),
('rowid-15299','GHBC-REQ-015299','GS 1207:2018',20,'20.8',NULL,'GHBC-C-004025','The concrete shall be deposited as close as practicable in the final position to avoid rehandling or moving of the concrete horizontally by vibration.','material',NULL,NULL,NULL,NULL,'[]','[]','["EN 206"]',0.9,'extracted','VERIFIED','2018','90a7fb282b23cc5ad71434fad78144c775f1a15282db3f66d7a0f3e319e6e937','2026-08-15 13:56:13'),
('rowid-15300','GHBC-REQ-015300','GS 1207:2018',20,'20.8',NULL,'GHBC-C-004025','Ready-mixed concrete shall be transported and delivered in accordance with BS EN 206.','material',NULL,NULL,NULL,NULL,'[]','[]','["EN 206"]',0.9,'extracted','VERIFIED','2018','54c211134ecf2ccd895d4303ecd9a21fbe717d653bbd842a5498f38b9b7b5821','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15301','GHBC-REQ-015301','GS 1207:2018',20,'20.9','20.9.1','GHBC-C-004026','Concrete shall not be placed until the Head of works''s consent has been given in writing, and the Owner or Owner‘s Authorised Agent shall give the Head of works at least one full working day''s notice of his intention to place concrete.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','f9be1051bbea7b5c4f0ce2e4b36ef07433736d48a1f3f5ca7a44a536303c263f','2026-08-15 13:56:13'),
('rowid-15302','GHBC-REQ-015302','GS 1207:2018',20,'20.9','20.9.1','GHBC-C-004026','If concrete placing is not commenced within 24 hours of the Head of works''s consent the Owner or Owner‘s Authorised Agent shall again request consent as specified above.','material',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":24,"unit":"h","operator":null,"context":"acing is not commenced within 24 hours of the Head of works''s co"}]','[]',0.93,'extracted','VERIFIED','2018','31194c559b2b033ecf78be032c495bb62826934586f0eb5869aacb3941e56ca3','2026-08-15 13:56:13'),
('rowid-15303','GHBC-REQ-015303','GS 1207:2018',20,'20.9','20.9.1','GHBC-C-004026','Concreting operations shall only be carried out during daylight hours unless adequate lighting arrangements have been made and the lights are in working order by noon.','electrical',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','e93f4fba2cfd8d2236fb797fc1e0adb86b308aeeb05eb0d79158f6d624f3d5c1','2026-08-15 13:56:13'),
('rowid-15304','GHBC-REQ-015304','GS 1207:2018',20,'20.9','20.9.1','GHBC-C-004026','Workmen shall not be allowed to work double shifts, and the Owner or Owner‘s Authorised Agent shall provide a fresh team for night shifts.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','4ff4fa70662d7760659a1efe2e12777f8b4c6999ebed7bb8512d070a7a0bbc52','2026-08-15 13:56:13'),
('rowid-15305','GHBC-REQ-015305','GS 1207:2018',20,'20.9','20.9.1','GHBC-C-004026','All placing and compaction of concrete shall be carried out under the direct supervision of an experienced concrete supervisor.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','0ed727523a0d3d1b51104171a5b505aa572020b13a961208cc2dab32b9dee48c','2026-08-15 13:56:13'),
('rowid-15306','GHBC-REQ-015306','GS 1207:2018',20,'20.9','20.9.1','GHBC-C-004026','Once the casting of concrete has begun, it shall be carried out in a continuous process between construction joints.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','54ae9c00e4fed0117181aa2130e76abb6bc8e1f2a83116e9422314286e7f5aaf','2026-08-15 13:56:13'),
('rowid-15307','GHBC-REQ-015307','GS 1207:2018',20,'20.9','20.9.2','GHBC-C-004027','Concrete shall be placed within 60 minutes of mixing.','material',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":60,"unit":"m","operator":null,"context":"ncrete shall be placed within 60 minutes of mixing."}]','[]',0.93,'extracted','VERIFIED','2018','5d22fb341fb60b696d450298048277ddbc027447d14dba9c0b91b58777bbf789','2026-08-15 13:56:13'),
('rowid-15308','GHBC-REQ-015308','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','concrete Excavated surfaces on which concrete is to be deposited shall be prepared as set out in this Code.','material',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','a0b82ab357eb47e1d08fa160994ef1ff27c75eb3f24fb189e8cb17554b0464a4','2026-08-15 13:56:13'),
('rowid-15309','GHBC-REQ-015309','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','Where specified or directed by the Head of works, excavated surfaces, shall be lined with an approved sheeting to provide a clean impervious layer.','approval',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','42c814ebdc78550a4efec116f997b8a98561b9f46f83d957ef10424c5481130c','2026-08-15 13:56:13'),
('rowid-15310','GHBC-REQ-015310','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','The lining material shall be of sufficient strength to provide a durable working surface, and to support the concrete and reinforcement without tearing.','structural',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','b393ebac893491308516c8e90b61f441a10cc073dddd6cd4f35ef109ec8961c5','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15311','GHBC-REQ-015311','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','The joints of the material between strips shall have a 150 mm overlap, and the lining shall be held firmly in position by nails, pegs, etc. Polyethylene sheeting shall have a minimum thickness of','material',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":150,"unit":"mm","operator":null,"context":"l between strips shall have a 150 mm overlap, and the lining shall"}]','["BS 1521"]',0.93,'extracted','VERIFIED','2018','460ed73156ffa1fabdbe129e8ca9ac21f2c78eab2be34f9c5b436d4fa44aedeb','2026-08-15 13:56:13'),
('rowid-15312','GHBC-REQ-015312','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','0.15 mm, and waterproof paper shall comply with BS 1521 Waterproof Building Paper, Class B, and shall have fibrous reinforcement.','structural',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":0.15,"unit":"mm","operator":null,"context":"0.15 mm, and waterproof paper shall c"}]','["BS 1521"]',0.93,'extracted','VERIFIED','2018','f37db2a4328e6f2cb3846e3447b5b91b4b8695cec0e83411981829683abb3fe6','2026-08-15 13:56:13'),
('rowid-15313','GHBC-REQ-015313','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','Existing concrete surfaces shall be prepared as set out in this Code.','material',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','3c5fa3b04461d1e6fb66894e2f50dee6944f770ceaed568d4400039ec58d28be','2026-08-15 13:56:13'),
('rowid-15314','GHBC-REQ-015314','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','All excavations and other contact surfaces of an absorbent nature shall be damp but no standing water shall be permitted to remain on these surfaces.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','f1eda3cafda929b03057e8af4478bc0f913a3474699f13a350bcde8ccb189d7f','2026-08-15 13:56:13'),
('rowid-15315','GHBC-REQ-015315','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','All formwork shall be clean on the inside.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','690530eeb9d814043952f769bb1161fa1999ee0b0e4e8f79f655da0d93d9b164','2026-08-15 13:56:13'),
('rowid-15316','GHBC-REQ-015316','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','If so required by the Head of works excavated surfaces against which concrete is to be placed shall receive a prior coating of mortar mixed in the proportions similar to those of the fines portion in the concrete to be placed.','material',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','4557c9150e6dc60831e4194225ae5255213222c0b29f68e93b8fd2d1e05e4c9e','2026-08-15 13:56:13'),
('rowid-15317','GHBC-REQ-015317','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','The mortar shall be kept ahead of the concrete, it shall be well worked into all parts of the excavated surface and it shall be not less than 5 mm thick.','material',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":5,"unit":null,"operator":"not less than","context":"vated surface and it shall be not less than 5 mm thick."},{"parameter":"measurement","value":5,"unit":"mm","operator":null,"context":"and it shall be not less than 5 mm thick."}]','["BS 1521"]',0.93,'extracted','VERIFIED','2018','ce9fd629dc43498d8a6e8b0f5bc98eebf976b5d07f410687e8a115a234b5fc85','2026-08-15 13:56:13'),
('rowid-15318','GHBC-REQ-015318','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','Fissures that have been cleaned out shall be filled with mortar or with concrete as instructed by the Head of works.','material',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','cefd5470ad1d8d47a63868badfa1ee980cb5e963f136fe3bdc6655064e3bf70b','2026-08-15 13:56:13'),
('rowid-15319','GHBC-REQ-015319','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','The amount of mortar placed at any one time shall be so controlled that it does not dry out or set before being covered with concrete.','material',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','b3d29ce6975ec1ac00a537f2ad9f5f9aa176b86aa2a0b36a61eb5f44eb273cd1','2026-08-15 13:56:13'),
('rowid-15320','GHBC-REQ-015320','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','Any flow of water into an excavation shall be diverted through proper side drains to a sump, or be removed by other suitable methods, so as to prevent the washing away of the freshly deposited concrete or any of its constituents.','material',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','45ea45ac995ba6f9dfdb4c2a6abe06a73159f8331d4136cec1a1b358229238a4','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15321','GHBC-REQ-015321','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','Any underdrains constructed for this purpose shall be fully grouted up when they are no longer required.','conditional',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','d5f22184c099319260e03f5e29908a11de422b265dc9f3909f55954a35c18551','2026-08-15 13:56:13'),
('rowid-15322','GHBC-REQ-015322','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','The Owner or Owner‘s Authorised Agent shall take precautions to ensure that no cement or concrete is dropped into water courses.','material',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','49f106947c54f886635b8160a1e70f39279996c1859c281c8bca38f6d5dff86b','2026-08-15 13:56:13'),
('rowid-15323','GHBC-REQ-015323','GS 1207:2018',20,'20.9','20.9.3','GHBC-C-004028','If required by the Environmental Management Plan, the Owner or Owner‘s Authorised Agent shall monitor the pH and turbidity of water courses and bodies in the vicinity of construction to ensure that water quality levels are maintained.','environmental',NULL,NULL,NULL,NULL,'[]','[]','["BS 1521"]',0.9,'extracted','VERIFIED','2018','694704b1d0ae24a8463883e32313cad2ada29fb09e17460e6bb87cd3a83135f9','2026-08-15 13:56:13'),
('rowid-15324','GHBC-REQ-015324','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','The concrete shall be deposited as near as possible to its final position.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','0c7e0860583b6f8073a79a7951f5a30fea409e17db9bf84fc327a22fb536889f','2026-08-15 13:56:13'),
('rowid-15325','GHBC-REQ-015325','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','Where possible, concrete shall be deposited vertically into its final position.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','3b3673e201d179e205f5a94338f1877addfca175380d13514a944cf5ded4f0e0','2026-08-15 13:56:13'),
('rowid-15326','GHBC-REQ-015326','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','It shall be placed so as to avoid','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','353b558f4a1345e775babd902fc615d361bcb33eb7050f1b42729b3d9d8e644f','2026-08-15 13:56:13'),
('rowid-15327','GHBC-REQ-015327','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','segregation of the concrete and displacement of the reinforcement, other embedded items, or formwork.','structural',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','26a21d8d2cbc6569619b42f14bd7a8b93f720162673fa2200d171bc6c2e67155','2026-08-15 13:56:13'),
('rowid-15328','GHBC-REQ-015328','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','When it is discharged above its place of final deposition, segregation shall be prevented by the use of chutes, downpipes, trunking, baffles or other appropriate devices.','conditional',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','776db491332088d9a9334be07d5a03975b5f9087df549100b5315f4936d5095c','2026-08-15 13:56:13'),
('rowid-15329','GHBC-REQ-015329','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','Forms for walls, columns and other thin clauses of significant height shall be provided with openings or other devices that will limit the height through which the fresh concrete has to fall, and thereby prevent segregation and accumulation of hardened concrete on the formwork or reinforcement above the level of the placed concrete.','structural',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','5420dba7efd9654e9b47fa5fca2ed030d64a68b4b5dfcb6401bbb2caa496d976','2026-08-15 13:56:13'),
('rowid-15330','GHBC-REQ-015330','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','In vertical elements such as walls or columns, concrete shall be brought up in layers of approximately uniform thicknesses parallel to the construction joint planes and between 200 and 500 mm thick unless otherwise permitted or directed by the Head of works.','structural',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":500,"unit":"mm","operator":null,"context":"nt planes and between 200 and 500 mm thick unless otherwise permit"}]','[]',0.93,'extracted','VERIFIED','2018','38369e861ff5514be1db66bd7efda9a1aab2184d9ce9d89d3ed8f4475c02122a','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15331','GHBC-REQ-015331','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','The layers shall be placed such that no feather edges are formed and before the preceding layer has taken its initial set.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','5273e8e53c40a6557547ccd0ddbcef10ce0b0d89da62fa681effe8a61000bdad','2026-08-15 13:56:13'),
('rowid-15332','GHBC-REQ-015332','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','In order to comply with this requirement, a layer may be started before completion of the preceding layer.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','8ce78b6ff00b5b3df78ee63e95b13ddd6f6e88792372a9f098d011d524c8d88c','2026-08-15 13:56:13'),
('rowid-15333','GHBC-REQ-015333','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','Fresh concrete shall not be placed against concrete that has been in position for more than 30 minutes, unless a construction joint is formed.','prohibited',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":30,"unit":null,"operator":"more than","context":"that has been in position for more than 30 minutes, unless a constructio"},{"parameter":"measurement","value":30,"unit":"m","operator":null,"context":"een in position for more than 30 minutes, unless a construction "}]','[]',0.93,'requires_review','DRAFT','2018','308b5e7e5422bef313b7a293f67699a9507390f127b24dec8e6bf0c149fc4d46','2026-08-15 13:56:13'),
('rowid-15334','GHBC-REQ-015334','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','In bridge decks of substantial thickness, care shall be taken to avoid layering of the concrete, and each panel or bay shall be placed to the full depth in one pass before proceeding to the next panel or bay.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','6f208a6956e4e10dba5b6b96f58d40075da672212a98a2b65d072713eb97d1ac','2026-08-15 13:56:13'),
('rowid-15335','GHBC-REQ-015335','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','All of the concrete in a single bay or pour shall be placed as a continuous operation.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','7f550b4569ee4d5c383e93ccef5fc3f68e1fd942687882352f881aa1f0ede62b','2026-08-15 13:56:13'),
('rowid-15336','GHBC-REQ-015336','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','It shall be carefully worked round all obstructions, irregularities in the foundations and the like so that all parts are completely filled with compacted concrete with no segregation or honeycombing.','structural',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','cc5b2ce20718837dad53dcf4411040360433cd07ef0369e2cbe38228fd933924','2026-08-15 13:56:13'),
('rowid-15337','GHBC-REQ-015337','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','It shall also be carefully worked round and between waterstops, reinforcement, embedded steelwork and similar items that protrude above the surface of the completed pour.','structural',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','7f1de527a56d63b8b3f6cf954fb76fc247e632acda31463dc2642aa8602b385d','2026-08-15 13:56:13'),
('rowid-15338','GHBC-REQ-015338','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','All work shall be completed on each batch of concrete before its initial set commences and thereafter the concrete shall not be disturbed before it has set hard.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','663de7b8a0cbe6150b26e52cae50177479f45a0c6e1421c6db90548ee22a7702','2026-08-15 13:56:13'),
('rowid-15339','GHBC-REQ-015339','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','No concrete that has','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','0ef1bc1fd1606a49de033f5226efaf526362c9a9f4ea1e6ff46f33b97be3adeb','2026-08-15 13:56:13'),
('rowid-15340','GHBC-REQ-015340','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','partially hardened during transit shall be used in the Works.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','aea125ab1a615c67e079d2d177b0b0a122987229290081550c8ea0d32d755284','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15341','GHBC-REQ-015341','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','Concrete shall not be placed during rain, which is sufficiently heavy or prolonged to wash mortar from coarse aggregate on the exposed faces of fresh concrete.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','6f35c2a7307ff794724e0a9eb499918eb33d2f7b7c8e4b4a3b0683d34758fda5','2026-08-15 13:56:13'),
('rowid-15342','GHBC-REQ-015342','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','Means shall be provided to remove any water accumulating on the surface of the placed concrete.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','209df0c8b16f91d78757b4100191f18162abd45ae3113c0f9b592580bb6bb167','2026-08-15 13:56:13'),
('rowid-15343','GHBC-REQ-015343','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','Concrete shall not be deposited into such accumulations of water.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','fa91d902d1302b34b9ae9c6d405ac2e4edeb0e6bbe30042bb70f0654c11a6942','2026-08-15 13:56:13'),
('rowid-15344','GHBC-REQ-015344','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','In drying weather, covers shall be provided for all fresh concrete surfaces that are not being worked on.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','0fcfc13490b45f372c738e3479746c1422d1a11ad56abb50160b668b067b789e','2026-08-15 13:56:13'),
('rowid-15345','GHBC-REQ-015345','GS 1207:2018',20,'20.9','20.9.4','GHBC-C-004029','Water shall not be added to concrete for any reason.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','1a747003e57d1b6d564d2fe9148ce4bd7983ddfe9f593fec882d285d32cf6eca','2026-08-15 13:56:13'),
('rowid-15346','GHBC-REQ-015346','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','Placing under water shall be allowed only in exceptional circumstances where it is unfeasible to dewater the location before the concrete is placed, and only if approved in the Environmental Management Plan.','environmental',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','372ca3575b9887b05fd61428a70b7838e2081e76f14ae0080c3cbf29a6bfdc46','2026-08-15 13:56:13'),
('rowid-15347','GHBC-REQ-015347','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','The pH of the water shall be monitored.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','204ddf59163c3b2219f0ec847c7124a15783b77dbdcad521628719039cfa22c2','2026-08-15 13:56:13'),
('rowid-15348','GHBC-REQ-015348','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','No concrete shall be placed in running water.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','e9de18d47814c81e77f53930f5f4796032c50207b2c780b3aa84bbafd147a4d2','2026-08-15 13:56:13'),
('rowid-15349','GHBC-REQ-015349','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','When it is necessary to place concrete under water the Owner or Owner‘s Authorised Agent shall submit to the Head of works his proposals for the method and equipment to be employed.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','20a6341eb3893e59f24c18a82a287049aefe1bcb73be877b6465523075b4246f','2026-08-15 13:56:13'),
('rowid-15350','GHBC-REQ-015350','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','The concrete shall be deposited either by bottom-discharging watertight containers or through funnel-shaped tremies with a trapdoor or sliding plug fitted at the discharging end.','plumbing',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','8e5ff056f17e91c7c81cf786ec8bc779da48bdf3ed5166732a14520e149422f9','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15351','GHBC-REQ-015351','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','When concreting by tremie, the pipe shall be kept continuously full with concrete to a level above the water and shall have the discharge end kept well below the surface of the concrete, in order to prevent air and water from entering the tremie.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','1d720ce4a42a6c17287ad616d40336c7152417a493656d7e5ef41c39ee8edc3e','2026-08-15 13:56:13'),
('rowid-15352','GHBC-REQ-015352','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','Should this seal be broken, or the level of the concrete is allowed to fall sufficiently for water to enter the pipe, the tremie shall be lifted, plugged and re-filled before concreting is recommenced.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','aed13f980f1ec1c4eca1c3226a59387167b9ae469ab5a0679eeaa71b37b256b3','2026-08-15 13:56:13'),
('rowid-15353','GHBC-REQ-015353','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','Special care shall be taken to control the rate of descent so as to avoid segregation.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','c4845d01bd30f89c00dabc5c3a0e73debee0df0ec1d1269b68297e66433aa23b','2026-08-15 13:56:13'),
('rowid-15354','GHBC-REQ-015354','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','Distribution of concrete by lateral movement of the tremie will not be permitted.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','fbe733c9949610d6fe4ec49e91e7bc3b7a067af839a513ebd1900a8a81025c64','2026-08-15 13:56:13'),
('rowid-15355','GHBC-REQ-015355','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','During and after concreting under water, pumping or de-watering in the immediate vicinity shall be suspended if there is any danger that','conditional',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','dda3e5c4ef2268dcd7f7a2d32207cdbc2b756b02c43a2ee404d6d6c400651833','2026-08-15 13:56:13'),
('rowid-15356','GHBC-REQ-015356','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','such work will disturb the freshly placed concrete.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','62d881a212da4f882a846d857ab98181b5473348dd652fe6eea1469f698a87aa','2026-08-15 13:56:13'),
('rowid-15357','GHBC-REQ-015357','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','The concrete mix to be placed under water shall be specially designed and approved for this purpose, to ensure good flowability, plasticity and cohesion.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','87962905278ab4b947714762ff45d26d7c43a9f1fedcc42b6a72ca55b07ce82c','2026-08-15 13:56:13'),
('rowid-15358','GHBC-REQ-015358','GS 1207:2018',20,'20.9','20.9.5','GHBC-C-004030','Increased sand and cement content over those of normal mixes will usually be required.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','d2b6b030b0da9d75f6728ac45c6ca31db2458c5bf5f55db14e9a04407a0f3045','2026-08-15 13:56:13'),
('rowid-15359','GHBC-REQ-015359','GS 1207:2018',20,'20.9','20.9.6','GHBC-C-004031','If concrete placing is interrupted for any reason and the duration of the interruption cannot be forecast or is likely to be prolonged, the Owner or Owner‘s Authorised Agent shall complete the compaction of the placed concrete and immediately take the necessary action to form a construction joint in accordance with this Code, Equipment and materials to comply with this requirement shall be readily available at all times during concrete placing.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','987ce62adedebd78f695bb07125b66b2e6c95f4ef8428f19d778db7cfb6d480a','2026-08-15 13:56:13'),
('rowid-15360','GHBC-REQ-015360','GS 1207:2018',20,'20.9','20.9.6','GHBC-C-004031','Before concreting is resumed after such an interruption the Owner or Owner‘s Authorised Agent shall cut out and remove all damaged, contaminated or uncompacted concrete, feather edges or any other undesirable features and shall leave a clean sound surface against which the fresh concrete may be placed.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','a662963fff3dd619fb587861d5a6fda42f496d7a78c85ad02f4c61b7ded0365b','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15361','GHBC-REQ-015361','GS 1207:2018',20,'20.9','20.9.6','GHBC-C-004031','If it becomes possible to resume concrete placing within 30 minutes of the stoppage and the Head of works consents to a resumption, the new concrete shall be thoroughly worked in and compacted against the surface of the existing concrete so as to avoid any cold joints.','material',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":30,"unit":"m","operator":null,"context":"esume concrete placing within 30 minutes of the stoppage and the"}]','[]',0.93,'extracted','VERIFIED','2018','ea634ace4f1fc7201fda4684b06ea7e41c2bc97ba804b6a943366396db188d08','2026-08-15 13:56:13'),
('rowid-15362','GHBC-REQ-015362','GS 1207:2018',20,'20.9','20.9.7','GHBC-C-004032','Unless otherwise approved by the Head of works, pours shall not be more than 2.0 m high and shall as far as possible have a uniform thickness over the plan area of the pour.','prohibited',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":2,"unit":null,"operator":"more than","context":" of works, pours shall not be more than 2.0 m high and shall as far as po"},{"parameter":"measurement","value":2,"unit":"m","operator":null,"context":" pours shall not be more than 2.0 m high and shall as far as poss"}]','[]',0.93,'requires_review','DRAFT','2018','08228395a0d9680c67dff1c711b55080965a7a829487fbd216d1526f24f89346','2026-08-15 13:56:13'),
('rowid-15363','GHBC-REQ-015363','GS 1207:2018',20,'20.9','20.9.7','GHBC-C-004032','Concrete shall be placed to the full planned height of all pours except in the circumstances described in this Code.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','59f7e1821f7b4996b312315ee5a63a84acc689caee20bca74734d1a0bb8129c3','2026-08-15 13:56:13'),
('rowid-15364','GHBC-REQ-015364','GS 1207:2018',20,'20.9','20.9.7','GHBC-C-004032','The Owner or Owner‘s Authorised Agent shall plan the dimensions and sequence of pours in such a way that cracking of the concrete does not take place due to thermal or shrinkage stresses.','energy',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','ffa8789b042ce94479ebb83d77e941a0d51fc8dea7cf8678abf3187ad9105edb','2026-08-15 13:56:13'),
('rowid-15365','GHBC-REQ-015365','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','The concrete shall be fully compacted throughout the full volumetric extent of the placed layer.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','40f3b0f3342bd10f17da45aaea26ebe6c795a9ba756afa04c0fd3f6dca77f015','2026-08-15 13:56:13'),
('rowid-15366','GHBC-REQ-015366','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','It shall be thoroughly worked against the formwork and around any reinforcement, tendons, ducts and other embedded items, without displacing them.','structural',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','5fb380a2c26906b1afb28a14cd4bb4c61b74d7665b282db9f7837fef1ce8361a','2026-08-15 13:56:13'),
('rowid-15367','GHBC-REQ-015367','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','Particular care shall be taken at arrises and other confined spaces.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','6f674cf49ebdfe8eb7eb1dc3d8e4954ced3a9131ab2c96744cb19ef6b7a21c23','2026-08-15 13:56:13'),
('rowid-15368','GHBC-REQ-015368','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','Successive layers of the same pour shall be thoroughly worked together.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','77b32ec73681436cc37229d0af4a47d5cf13566b394d1f55b147d09c336642f4','2026-08-15 13:56:13'),
('rowid-15369','GHBC-REQ-015369','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','In bridge decks with void formers, adequate means to prevent fplotation shall be employed, and care shall be taken to ensure adequate compaction of the concrete placed beneath the void formers.','planning',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','4b4153b6113dd69d93060d88d2b740136658b35dec8b3c13f774afc31cea797b','2026-08-15 13:56:13'),
('rowid-15370','GHBC-REQ-015370','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','Concrete shall be compacted with the assistance of mechanical immersion vibrators, unless the Head of works agrees to another method.','mechanical',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','192eee85829949c7e5672027ee6173e475e150d3982c15519e16a7d105551fa1','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15371','GHBC-REQ-015371','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','A sufficient number of vibrators shall be operated to enable the entire quantity of concrete being placed to be vibrated for the necessary period and, in addition, stand-by vibrators shall be available for instant use at each location where concrete is being placed.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','298c182fd4c826c95cf4bc58e7e0abe8533c255e13ce0db8619279157b56a966','2026-08-15 13:56:13'),
('rowid-15372','GHBC-REQ-015372','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','Where the concrete contains aggregate with a nominal size of 63 mm or more, vibrators with a diameter of 100 mm or more shall be used.','material',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":63,"unit":"mm","operator":null,"context":"regate with a nominal size of 63 mm or more, vibrators with a dia"},{"parameter":"measurement","value":100,"unit":"mm","operator":null,"context":" vibrators with a diameter of 100 mm or more shall be used."}]','[]',0.93,'extracted','VERIFIED','2018','8a61f952b6276ff65a3412dc3b0240e975c503d95cd2aa6a4393e226d3ce5a51','2026-08-15 13:56:13'),
('rowid-15373','GHBC-REQ-015373','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','Vibration shall be applied by experienced workmen, and over-vibration resulting in segregation, surface water and leakage, shall be avoided.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','0afde33ffad4413913239d88eb4bdb0b4414d489387ade35a78418695a85d464','2026-08-15 13:56:13'),
('rowid-15374','GHBC-REQ-015374','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','Vibration shall be continued at each point until the concrete ceases to contract, a thin layer of mortar has appeared on the surface and air bubbles have ceased to appear.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','47ea9ea418487b2f04868e90cb46b3834f3eb4d7c3034767fac639527a9c5f30','2026-08-15 13:56:13'),
('rowid-15375','GHBC-REQ-015375','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','Vibrators shall not be used to move concrete laterally and shall be withdrawn slowly to prevent the formation of voids.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','70465df37654b6250c40889434891637998ab338b709835d9c91f7fb6b0b607a','2026-08-15 13:56:13'),
('rowid-15376','GHBC-REQ-015376','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','Vibration shall not be applied by shaking the reinforcement nor shall vibrators be allowed to touch reinforcement or other embedded items.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','e5c39ebebfb71ecb1c2fd846f011e727638cd585fbf5f7b2bf7b54d500f87326','2026-08-15 13:56:13'),
('rowid-15377','GHBC-REQ-015377','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','The vibrators shall be inserted vertically into the concrete to penetrate the layer underneath at regular spacing, which shall not exceed the distance from the vibrator over which vibration is visibly effective.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','0814c03f9d3dd8acfa6042386ff69486ac27a5234656f468e6ab86ab4f94a96c','2026-08-15 13:56:13'),
('rowid-15378','GHBC-REQ-015378','GS 1207:2018',20,'20.10',NULL,'GHBC-C-004033','Special attention shall be given in prestressing anchor zones, behind anchor plates and in places where a high concentration of reinforcing steel or cables occurs.','structural',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','d4acd183f6edb0433fc608b075aee8e359759e80f2bdd134fdd3fa257f5a819f','2026-08-15 13:56:13'),
('rowid-15379','GHBC-REQ-015379','GS 1207:2018',20,'20.11','20.11.1','GHBC-C-004034','During the first stage of hardening, concrete shall be protected from loss of moisture and from the development of temperature differentials within the concrete, which may be sufficient to cause cracking.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','7e23f037dcce98d017d734cc694f80dc454f55acceb19dfc199a368f09decf26','2026-08-15 13:56:13'),
('rowid-15380','GHBC-REQ-015380','GS 1207:2018',20,'20.11','20.11.1','GHBC-C-004034','Curing shall be continued for at least 7 days for concrete made with CEM I cement and for at least 10 days for concrete made with CEM II and CEM III cement, or until the concrete is covered by later construction, whichever is the shorter period.','material',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":7,"unit":null,"operator":"at least","context":"Curing shall be continued for at least 7 days for concrete made with C"},{"parameter":"comparison","value":10,"unit":null,"operator":"at least","context":"ade with CEM I cement and for at least 10 days for concrete made with C"},{"parameter":"measurement","value":7,"unit":"days","operator":null,"context":"all be continued for at least 7 days for concrete made with CEM I "},{"parameter":"measurement","value":10,"unit":"days","operator":null,"context":"CEM I cement and for at least 10 days for concrete made with CEM II"}]','[]',0.93,'extracted','VERIFIED','2018','a834c2cd04891017c3086dbe3fd55044d8464f53451d7127f392117641ecbe3e','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15381','GHBC-REQ-015381','GS 1207:2018',20,'20.11','20.11.1','GHBC-C-004034','The curing process shall commence as soon as the concrete has hardened sufficiently to resist damage from the process.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','2b180eb1e7ee393fb5d9ee017c24e8f4d018af9531b91098a057bdd1854b0cac','2026-08-15 13:56:13'),
('rowid-15382','GHBC-REQ-015382','GS 1207:2018',20,'20.11','20.11.1','GHBC-C-004034','In the case of large areas or continuous pours, the curing process shall commence on the completed clauses before completion of the remaining pour.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','eaaa47bce6a69319eff062613e1edba44292d2c72355240a220e4bed74ed9fe5','2026-08-15 13:56:13'),
('rowid-15383','GHBC-REQ-015383','GS 1207:2018',20,'20.11','20.11.1','GHBC-C-004034','Details of the Owner or Owner‘s Authorised Agent''s proposals for curing concrete shall be submitted to the Head of works for approval before the placing of concrete commences.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','df3d3a0e3b264108af8dfa08e067f0ded94c5f7a506831f1929b1e9ff00e3464','2026-08-15 13:56:13'),
('rowid-15384','GHBC-REQ-015384','GS 1207:2018',20,'20.11','20.11.1','GHBC-C-004034','In addition, the Owner or Owner‘s Authorised Agent shall, where feasible, provide a suitable form of shading to prevent the direct rays of the sun reaching the concrete surfaces for at least the first four days of the curing period.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','eb0af9733a4642a92b709dc7cd5e4ce50fc99dcb830f1d07342efa641dc50ec0','2026-08-15 13:56:13'),
('rowid-15385','GHBC-REQ-015385','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','Protection against loss of moisture shall be achieved by one or more of the following methods:','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','4d108656b4c8afd9ce414c046b233cfebb02504824d25429eed910418a5f7121','2026-08-15 13:56:13'),
('rowid-15386','GHBC-REQ-015386','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','(i) Retaining formwork in place for the full curing period.','informational',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','eba5b8587c490878c980add4aec02f6bb7197bfdb8a35d1c170da7b19685fa4c','2026-08-15 13:56:13'),
('rowid-15387','GHBC-REQ-015387','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','(ii) Closely covering exposed concrete surfaces with impermeable sheeting, properly secured to prevent its removal by wind and the development of air spaces beneath it.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','a2294834364d171f51b728f9eebc8b0eeba98da35b6955550fc29225d19233f1','2026-08-15 13:56:13'),
('rowid-15388','GHBC-REQ-015388','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','Joints in the sheeting shall be lapped by at least 300 mm.','mandatory',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":300,"unit":null,"operator":"at least","context":"e sheeting shall be lapped by at least 300 mm."},{"parameter":"measurement","value":300,"unit":"mm","operator":null,"context":"g shall be lapped by at least 300 mm."}]','[]',0.93,'extracted','VERIFIED','2018','1d2fb885cc8de1d0f90f75736c76b4574cd54a0117119b8f0a9c107d1a404703','2026-08-15 13:56:13'),
('rowid-15389','GHBC-REQ-015389','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','(iii) Covering with sand or with mats made from a moisture retaining material, and keeping the covering constantly wet.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','9e64b3138751779dc4be9029dff09ab76c822a7cd9765bd59db1dcab6e459057','2026-08-15 13:56:13'),
('rowid-15390','GHBC-REQ-015390','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','(iv) Keeping the exposed surfaces continuously wet by means of a water spray, only where other methods are not possible.','conditional',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','0711a703f8f17c2acbe40c64d4497023098973c3c3d47c28b5ca6fa849deddbc','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15391','GHBC-REQ-015391','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','Alternate wetting and drying, and cold water on warm concrete surfaces shall be avoided.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','51e55ac4540f05a1acecf565f7222b5e1ad96a716394d70d25df7c975a24c328','2026-08-15 13:56:13'),
('rowid-15392','GHBC-REQ-015392','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','This method shall not be used in the case of thick concrete clauses or in other situations where there is a risk of a high temperature differential between the concrete surface and its core.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','f589a63374c0d120ded5fc5f92224a9b9b35d6a55cac60c53ad433612305f123','2026-08-15 13:56:13'),
('rowid-15393','GHBC-REQ-015393','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','Water used for curing shall comply with Subclause (d).','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','fb5bc14a1ac9e765270a048914b91657f29e7dbb8324951642565f32fc97000e','2026-08-15 13:56:13'),
('rowid-15394','GHBC-REQ-015394','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','(v) If use of the foregoing methods is inappropriate, surfaces that will not have further concrete bonded to them and which are not to receive an application of a finish may be cured by the application of a curing compound having an efficiency index of at least 90%.','material',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":90,"unit":null,"operator":"at least","context":"having an efficiency index of at least 90%."},{"parameter":"measurement","value":90,"unit":"%","operator":null,"context":" efficiency index of at least 90%."}]','[]',0.93,'extracted','VERIFIED','2018','fa7ff732f29ae7763877de1734bd65b12d407c4d4d45869cad87e4f4b5ee29ff','2026-08-15 13:56:13'),
('rowid-15395','GHBC-REQ-015395','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','Curing compounds shall contain a fugitive dye to enable the extent of the spread to be seen easily.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','e9566835799f637925d4486a57655b9bfa5b3cb4bb2bbfe1e67c2d865ff4b64e','2026-08-15 13:56:13'),
('rowid-15396','GHBC-REQ-015396','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','Curing compound used on surfaces exposed to sunlight shall contain sufficient finely divided flake aluminium in suspension to produce a complete coverage of the surface with a metallic finish when applied at the rate recommended by the manufacturer.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','3cb0e0a420bb5723b4015e12cc363c9cf63c5f81d8ccaf2383bdeffd779b678d','2026-08-15 13:56:13'),
('rowid-15397','GHBC-REQ-015397','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','Curing compounds shall become stable and impervious to the evapouration of water from the concrete surface within 60 minutes of application.','material',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":60,"unit":"m","operator":null,"context":"m the concrete surface within 60 minutes of application."}]','[]',0.93,'extracted','VERIFIED','2018','c7f054f5e6bc0abb2956a89fe421e8b03e1d695ad2e429ae080dc7143ad4a0c1','2026-08-15 13:56:13'),
('rowid-15398','GHBC-REQ-015398','GS 1207:2018',20,'20.11','20.11.2','GHBC-C-004035','The material shall not react chemically with the concrete and shall not crack, peel or disintegrate within three weeks after application.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','53b352adf5d2ecdc200ce3b7c80f5679ea5e3528e03876724e8a8569c9101a2d','2026-08-15 13:56:13'),
('rowid-15399','GHBC-REQ-015399','GS 1207:2018',20,'20.11','20.11.3','GHBC-C-004036','differentials The Owner or Owner‘s Authorised Agent shall limit the development of temperature differentials in concrete after placing by any means appropriate to the circumstances including the following:','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','45a0b34938c734b9da8ef8763809c862ac85b8f8b44ab0ab4782a856f334e50e','2026-08-15 13:56:13'),
('rowid-15400','GHBC-REQ-015400','GS 1207:2018',20,'20.11','20.11.3','GHBC-C-004036','(i) limiting concrete temperatures at placing as set out in Subclause; (ii) use of low heat cement, subject to the approval of the Head of works; (iii) insulation of exposed concrete surfaces by insulating blankets.','energy',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','b12ec23109207356f3996a5e550ceaa6332288aaeab4804fc391af6496ae7d08','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15401','GHBC-REQ-015401','GS 1207:2018',20,'20.11','20.11.3','GHBC-C-004036','Such blankets shall have an insulation value at least equivalent to 50 mm of dry mineral wool; (iv) leaving formwork in place during the curing period.','energy',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":50,"unit":"mm","operator":null,"context":" value at least equivalent to 50 mm of dry mineral wool; (iv) lea"}]','[]',0.93,'extracted','VERIFIED','2018','03f089d020ca35249db8b3fab7ef7a97560a5e6c80ad79937980978ac8706a3f','2026-08-15 13:56:13'),
('rowid-15402','GHBC-REQ-015402','GS 1207:2018',20,'20.11','20.11.3','GHBC-C-004036','Steel forms shall be suitably insulated on their external surfaces; (v) preventing rapid dissipation of heat from surfaces by shielding from wind; (vi) avoiding the use of water sprays when such use would cause rapid cooling of the surface.','energy',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','0419e90fb3dec1b36e9284230ebb047990964176ea8e8fb7f72ad3a901363670','2026-08-15 13:56:13'),
('rowid-15403','GHBC-REQ-015403','GS 1207:2018',20,'20.12',NULL,'GHBC-C-004037','Freshly placed concrete shall be protected from rainfall and from water running over the surface until it is sufficiently hard to resist damage from these causes.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','0a88d6ab027e3811b45093c2abf4e193242914cd3951dfb5b01bd6af752957f8','2026-08-15 13:56:13'),
('rowid-15404','GHBC-REQ-015404','GS 1207:2018',20,'20.12',NULL,'GHBC-C-004037','No traffic shall be allowed on any concrete surface until such time as it is hard enough to resist damage by such traffic.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','7a1ec2f27901eff175998d79f25a7caaf71e57cd3fc6a18d0fb8c87fcdd75e3f','2026-08-15 13:56:13'),
('rowid-15405','GHBC-REQ-015405','GS 1207:2018',20,'20.12',NULL,'GHBC-C-004037','Concrete placed in the Works shall not be subject to any loading until it has attained at least its nominal strength as defined in this Code.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','e0a4e61d71ef96d5a2f743a45f6c270bc37259008a536f3771699f11ed98688a','2026-08-15 13:56:13'),
('rowid-15406','GHBC-REQ-015406','GS 1207:2018',20,'20.12',NULL,'GHBC-C-004037','No load shall be applied to any part of the structure until the specified curing period has expired, after which applied loading shall be allowed only when approved by the Head of works.','approval',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','543e771723d6216f69a2be19ef5c0bbe4a896043a63d9f3c2b84672c5a0d1ff9','2026-08-15 13:56:13'),
('rowid-15407','GHBC-REQ-015407','GS 1207:2018',20,'20.12',NULL,'GHBC-C-004037','The Head of works‘s decision will be based on the type of load to be applied, the age of the structure, the magnitude of stress induced and the propping of the structure.','dimensional',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','688db5cc07aed34291202d1e93bc7fe51c05cb466e01bfbea13247da0474a9b8','2026-08-15 13:56:13'),
('rowid-15408','GHBC-REQ-015408','GS 1207:2018',20,'20.12',NULL,'GHBC-C-004037','If the Owner or Owner‘s Authorised Agent desires to impose loads on newly-placed concrete, he shall make at least three test cubes and cure them in the same conditions as the concrete they represent.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','071eeff9a60999da042c04bb30d6dbfe224cb639989cea7edcbfa3fd11e0eae3','2026-08-15 13:56:13'),
('rowid-15409','GHBC-REQ-015409','GS 1207:2018',20,'20.12',NULL,'GHBC-C-004037','These cubes shall be tested singly at suitable intervals in order to estimate the time at which the required strength is reached.','inspection',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','c7fdeeb6a9ac53bcc2d1d48b7bba9df65c4b21f2fc7ef6106973012eeb2dc582','2026-08-15 13:56:13'),
('rowid-15410','GHBC-REQ-015410','GS 1207:2018',20,'20.12',NULL,'GHBC-C-004037','No structure shall be opened to traffic until the test samples made from the concrete in all parts of the structure have attained the specified minimum 28-day compressive strength.','material',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','64f0e930a8d28f3b5bbd1ab7ef966f753c58322cfeb95b17eef5d1f69fbe9702','2026-08-15 13:56:13');
INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15411','GHBC-REQ-015411','GS 1207:2018',20,'20.13',NULL,'GHBC-C-004038','During hot weather the Owner or Owner‘s Authorised Agent shall take all measures necessary to ensure that the temperature of concrete at the time of placing does not exceed 30°C and that the risk of moisture loss from the concrete during transporting and placing is minimised.','material',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":30,"unit":"°c","operator":null,"context":"me of placing does not exceed 30°C and that the risk of moisture"}]','[]',0.65,'requires_review','DRAFT','2018','f8148316673f30d5857dfe344b16c9a3c9ab030f3b3e6f9583f8a7bcc5edb64b','2026-08-15 13:56:13'),
('rowid-15412','GHBC-REQ-015412','GS 1207:2018',20,'20.13',NULL,'GHBC-C-004038','Such measures include but are not necessarily limited to the following:-','informational',NULL,NULL,NULL,NULL,'[]','[]','[]',0.62,'requires_review','DRAFT','2018','bed00847757f602d1af73beaa337f328bfbfca817db12219b49d50530cf61785','2026-08-15 13:56:13'),
('rowid-15413','GHBC-REQ-015413','GS 1207:2018',20,'20.13',NULL,'GHBC-C-004038','(i) Shielding aggregate stockpiles from direct sunshine.','informational',NULL,NULL,NULL,NULL,'[]','[]','[]',0.62,'requires_review','DRAFT','2018','286de6d725cec551f4a27c15b02d283d7402166f0c2954a0866a8cee85866b06','2026-08-15 13:56:13'),
('rowid-15414','GHBC-REQ-015414','GS 1207:2018',20,'20.13',NULL,'GHBC-C-004038','(ii) Use of a mist water spray on aggregates to promote cooling down by evapouration.','informational',NULL,NULL,NULL,NULL,'[]','[]','[]',0.62,'requires_review','DRAFT','2018','fecc31e4fc1ddbe413457aee55dd0953fc963173fde1baf69086e1fbaec65294','2026-08-15 13:56:13'),
