INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-15901','GHBC-REQ-015901','GS 1207:2018',22,'22.13','22.13.11.3.4','GHBC-C-004190','Concrete and masonry chimneys for high-heat appliances shall have approved clearance from buildings and structures to prevent overheating combustible materials, permit inspection and maintenance operations on the chimney and prevent danger of burns to persons.','fire',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','d2ee9301fc705769d12062907347adc4b6755cb71ef35b41ececabe417fa6ba3','2026-08-15 13:56:13'),
('rowid-15902','GHBC-REQ-015902','GS 1207:2018',22,'22.13','22.13.12','GHBC-C-004191','Clay flue liners shall be installed in accordance with ASTM C1283 and extend from a point not less than 203 mm (8 inches) below the lowest inlet or, in the case of fireplaces, from the top of the smoke chamber to a point above the enclosing walls.','fire',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":203,"unit":null,"operator":"not less than","context":"C1283 and extend from a point not less than 203 mm (8 inches) below the lowes"},{"parameter":"measurement","value":203,"unit":"mm","operator":null,"context":"nd from a point not less than 203 mm (8 inches) below the lowest i"},{"parameter":"measurement","value":8,"unit":"in","operator":null,"context":"a point not less than 203 mm (8 inches) below the lowest inlet o"}]','[]',0.93,'extracted','VERIFIED','2018','9258323b83f828c67d13b9ec47f079c388bc87fb3b9d8f13ffbe41b05eb2192d','2026-08-15 13:56:13'),
('rowid-15903','GHBC-REQ-015903','GS 1207:2018',22,'22.13','22.13.12','GHBC-C-004191','The lining shall be carried up vertically, with a maximum slope not greater than 30 degrees (0.52 rad) from the vertical.','mandatory',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":30,"unit":null,"operator":"not greater than","context":"tically, with a maximum slope not greater than 30 degrees (0.52 rad) from the v"}]','[]',0.93,'extracted','VERIFIED','2018','f773b438a3e93e4b263a380e4a83d33686ca5290bbb6775fe524482ea7c7a3c0','2026-08-15 13:56:13'),
('rowid-15904','GHBC-REQ-015904','GS 1207:2018',22,'22.13','22.13.12','GHBC-C-004191','Clay flue liners shall be laid in medium-duty nonwater-soluble refractory mortar conforming to ASTM C199 with tight mortar joints left smooth on the inside and installed to maintain an airspace or insulation not to exceed the thickness of the flue liner separating the flue liners from the interior face of the chimney masonry walls.','energy',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','05412835cbb856838d999043ef693d763334bbb1f2e0e05a982361e99b60f9ea','2026-08-15 13:56:13'),
('rowid-15905','GHBC-REQ-015905','GS 1207:2018',22,'22.13','22.13.12','GHBC-C-004191','Flue lining shall be supported on all sides.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','1f8f4b13afb1e9fa549ce213316e286103168972cbb7ddebf90a5a4d7f3745df','2026-08-15 13:56:13'),
('rowid-15906','GHBC-REQ-015906','GS 1207:2018',22,'22.13','22.13.12','GHBC-C-004191','Only enough mortar shall be placed to make the joint and hold the liners in position.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','a05c8600e50e38d7f8f42f760128c6883e5474a366b7a95108fb9064eb29e31d','2026-08-15 13:56:13'),
