INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-16851','GHBC-REQ-016851','GS 1207:2018',24,NULL,'24.8.5.3.2','GHBC-C-004431','Bearing and exterior wall studs shall be capped with double top plates installed to provide overlapping at corners and at interclauses with other partitions.','mandatory',NULL,NULL,NULL,NULL,'["A single top plate is permitted, provided that the plate is adequately tied at corners and intersecting walls by not less than the equivalent of 76 mm by 152 mm (3-inch by 6-inch) by 0.914 mm (0.036-inch-thick) galvanized steel plate that is nailed to each wall or segment of wall by six 8d [21 / ‖ × 0.113‖ (64mm by 2.87 mm)] box nails or equivalent on2 each side of the joint. For the butt-joint splice between adjacent single top plates, not less than the equivalent of a 76 mm by 304 mm (3-inch by 12-inch) by 0.914 mm-thick (0.036-inch) galvanized steel plate that is nailed to each wall or segment of wall by 12 8d [21 / -inch × 0.113inch (64 mm by 2.87 mm)] box nails on each2 side of the joint shall be required, provided that the rafters, joists or trusses are centered over the studs with a tolerance of not more than 25 mm (1 inch). The top plate shall not be required over headers that are in the same plane and in line with the upper surface of the adjacent top plates and are tied to adjacent wall clauses as required for the butt joint splice between adjacent single top plates. Where bearing studs are spaced at 610 mm (24inch) intervals, top plates are less than two 2inch by 6-inch (51 mm by 152 mm) or two 3-inch by 4-inch (76 mm by 102 mm) members and the floor joists, floor trusses or roof trusses that they support are spaced at more than 16-inch (406 mm) intervals, such joists or trusses shall bear within 5 inches (127 mm) of the studs beneath or a third plate shall be installed."]','[]','[]',0.62,'requires_review','DRAFT','2018','4b18e62f998efcd72f4f7b7f296ba4830dc79497c90a78055ea3008143fd4dfc','2026-08-15 13:56:13'),
