INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-18571','GHBC-REQ-018571','GS 1207:2018',28,'28.5','28.5.2.5.1','GHBC-C-004804','The values shall be corrected for the presence of window bars, glazing and external obstructions, if any.','conditional',NULL,NULL,NULL,NULL,'[]','[]','[]',0.62,'requires_review','DRAFT','2018','37a400f47889c3240ab5db87c574c86c26742b2e6be7d45996f6458e6ed3d3c7','2026-08-15 13:56:13'),
('rowid-18572','GHBC-REQ-018572','GS 1207:2018',28,'28.5','28.5.2.5.1','GHBC-C-004804','This assumes the maintenance of a regular cleaning schedule.','informational',NULL,NULL,NULL,NULL,'[]','[]','[]',0.62,'requires_review','DRAFT','2018','270eefc59eab2dacab6ac7f142164e8ce083814f7b92e320557192f56f8028e9','2026-08-15 13:56:13'),
