INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-22241','GHBC-REQ-022241','GS 1207:2018',29,NULL,'29.5.10.4.1.2','GHBC-C-005670','Each individual tank shall be located with respect to the nearest important building or group of buildings or line of adjoining property which may be built in accordance with Table 1.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','5fe758c355e76244d18a2c38f74ebfcab128211f1df66641b96209a237d99ab4','2026-08-15 13:56:13'),
('rowid-22242','GHBC-REQ-022242','GS 1207:2018',29,NULL,'29.5.10.4.1.2','GHBC-C-005670','The distances given refer to the horizontal distance in plan between the nearest point of the storage tank and building/property line.','dimensional',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','d3152feae5510ebe5cdd10b7eceb759e20e35d379f32d683f7a80afd3ec7a6f7','2026-08-15 13:56:13'),
('rowid-22243','GHBC-REQ-022243','GS 1207:2018',29,NULL,'29.5.10.4.1.2','GHBC-C-005670','29.5.10.4.1.3 In heavily populated or congested areas the authority may determine the need for other reasonable protective methods to be taken, such as provisions of fire walls, etc, If fire walls are to be provided, the authority may determine the extent to which the safety distances for above ground tanks may be reduced.','fire',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":1.3,"unit":"in","operator":null,"context":"29.5.10.4.1.3 In heavily populated or congeste"}]','[]',0.93,'extracted','VERIFIED','2018','085e45d000a7e6b66f00c2ed609c003e9764c469cde2348fa0dab2230c32e76e','2026-08-15 13:56:13'),
('rowid-22244','GHBC-REQ-022244','GS 1207:2018',29,NULL,'29.5.10.4.1.4','GHBC-C-005671','No LPG tank(s) shall be located within the bunded enclosures of any petroleum installation.','mandatory',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','ac9626405daea7cd8ed5282facb5eeb20adc1901b26d8c459ea8ab3fbf7b88b0','2026-08-15 13:56:13'),
