INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-23281','GHBC-REQ-023281','GS 1207:2018',29,NULL,'29.6.12.8','GHBC-C-005919','Where approved by the building official, mechanical smoke control for large enclosed volumes, such as in atriums or malls, shall be permitted to utilize the exhaust method.','fire',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','e1a93b614a47b72d882fd5b8c428f070712861e8e4b264965782484791030ad1','2026-08-15 13:56:13'),
('rowid-23282','GHBC-REQ-023282','GS 1207:2018',29,NULL,'29.6.12.8','GHBC-C-005919','Smoke control systems using the exhaust method shall be designed in accordance with Ghana Fire Code.','fire',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','92f24e3bf3347772e962117ca4e737aa85000d8d431ec1e8ee41d1f8d3482ab3','2026-08-15 13:56:13'),
('rowid-23283','GHBC-REQ-023283','GS 1207:2018',29,NULL,'29.6.12.8.1','GHBC-C-005920','The height of the lowest horizontal surface of the accumulating smoke layer shall be maintained not less than 6 feet (1829 mm) above any walking surface that forms a portion of a required egress system within the smoke zone.','fire',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":6,"unit":null,"operator":"not less than","context":"oke layer shall be maintained not less than 6 feet (1829 mm) above any walk"},{"parameter":"measurement","value":6,"unit":"feet","operator":null,"context":"l be maintained not less than 6 feet (1829 mm) above any walking s"},{"parameter":"measurement","value":1829,"unit":"mm","operator":null,"context":"ntained not less than 6 feet (1829 mm) above any walking surface th"}]','[]',0.93,'extracted','VERIFIED','2018','cca0d28d4e2a9a2b76a1d20cd5480845fc95f29cc8234007c634844b4c1382d9','2026-08-15 13:56:13'),
('rowid-23284','GHBC-REQ-023284','GS 1207:2018',29,NULL,'29.6.12.9','GHBC-C-005921','The design fire shall be based on a rational analysis performed by the registered design professional and approved by the Code official.','fire',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','9f14d8fb678e0a0ca8c6a4560b100c31833bd9c9f660835209ba6558a6527ea3','2026-08-15 13:56:13'),
('rowid-23285','GHBC-REQ-023285','GS 1207:2018',29,NULL,'29.6.12.9','GHBC-C-005921','The design fire shall be based on the analysis in accordance with Clause 29.6.12.4 and this clause.','fire',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','362064f5d4e4d742391d4e2d94a8f736a5d895327dd97721a4b41efa9fb889c2','2026-08-15 13:56:13'),
