INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-23291','GHBC-REQ-023291','GS 1207:2018',29,NULL,'29.6.12.10','GHBC-C-005926','Equipment such as, but not limited to, fans, ducts, automatic dampers and balance dampers shall be suitable for their intended use, suitable for the probable exposure temperatures that the rational analysis indicates, and as approved by the Code official.','mechanical',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','de7a7ca79d52ba886666065765c581d53a0e572359fb275226539dd1403cfa05','2026-08-15 13:56:13'),
('rowid-23292','GHBC-REQ-023292','GS 1207:2018',29,NULL,'29.6.12.10.1','GHBC-C-005927','Components of exhaust fans shall be rated and certified by the manufacturer for the probable temperature rise to which the components will be exposed.','mechanical',NULL,NULL,NULL,NULL,'["Reduced T as calculated s based on the assurance of adequate dilution air."]','[]','[]',0.9,'extracted','VERIFIED','2018','f8f3ed2b18aed1b405e8c6fedf52f772920eab5c72fb179632fc17bb277ed01e','2026-08-15 13:56:13'),
('rowid-23293','GHBC-REQ-023293','GS 1207:2018',29,NULL,'29.6.12.10.1','GHBC-C-005927','This temperature rise shall be computed by:','mandatory',NULL,NULL,NULL,NULL,'["Reduced T as calculated s based on the assurance of adequate dilution air."]','[]','[]',0.9,'extracted','VERIFIED','2018','bd88cce5073456ea0ad6f039ff9d279f2d6b9af80d85ef04b78133b28ad69a3f','2026-08-15 13:56:13'),
('rowid-23294','GHBC-REQ-023294','GS 1207:2018',29,NULL,'29.6.12.10.1','GHBC-C-005927','T =(Q /mc)+(T ) (Equation 5-3) s c a','informational',NULL,NULL,NULL,NULL,'["Reduced T as calculated s based on the assurance of adequate dilution air."]','[]','[]',0.9,'extracted','VERIFIED','2018','88c7e789f2e6c9074cb6968ddcc7ddc5ecbbf9cc8c562e18999922a8e9cdfed1','2026-08-15 13:56:13'),
