('rowid-25519','GHBC-REQ-025519','GS 1207:2018',33,'33.2','33.2.6.2','GHBC-C-006672','Columns or pilasters, including bases and moldings, shall not project more than 305 mm (12 inches).','prohibited',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":305,"unit":null,"operator":"more than","context":"d moldings, shall not project more than 305 mm (12 inches)."},{"parameter":"measurement","value":305,"unit":"mm","operator":null,"context":", shall not project more than 305 mm (12 inches)."},{"parameter":"measurement","value":12,"unit":"in","operator":null,"context":"not project more than 305 mm (12 inches)."}]','[]',0.93,'requires_review','DRAFT','2018','90609e044938ecba44cea1377ef54491674d34ecaf31d082ce37675211dd88be','2026-08-15 13:56:14'),
('rowid-25520','GHBC-REQ-025520','GS 1207:2018',33,'33.2','33.2.6.2','GHBC-C-006672','Belt courses, lintels, sills, architraves, pediments and similar architectural features shall not project more than 102 mm (4 inches).','prohibited',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":102,"unit":null,"operator":"more than","context":"al features shall not project more than 102 mm (4 inches)."},{"parameter":"measurement","value":102,"unit":"mm","operator":null,"context":"s shall not project more than 102 mm (4 inches)."},{"parameter":"measurement","value":4,"unit":"in","operator":null,"context":"not project more than 102 mm (4 inches)."}]','[]',0.93,'requires_review','DRAFT','2018','d67de19f66923f2bbba813014b27e92af18b504d488840982a397e7ee7d24dba','2026-08-15 13:56:14');
