('rowid-25529','GHBC-REQ-025529','GS 1207:2018',33,'33.2','33.2.7.2','GHBC-C-006676','Where the vertical clearance above grade to projecting windows, balconies, architectural features or mechanical equipment is more than 2438 mm (8 feet), 25 mm (1 inch) of encroachment is permitted for each additional 25 mm (1 inch) of clearance above 2438 mm (8 feet), but the maximum encroachment shall be 1219 mm (4 feet).','mechanical',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":2438,"unit":null,"operator":"more than","context":"es or mechanical equipment is more than 2438 mm (8 feet), 25 mm (1 inch) o"},{"parameter":"measurement","value":2438,"unit":"mm","operator":null,"context":"anical equipment is more than 2438 mm (8 feet), 25 mm (1 inch) of e"},{"parameter":"measurement","value":8,"unit":"feet","operator":null,"context":"uipment is more than 2438 mm (8 feet), 25 mm (1 inch) of encroachm"},{"parameter":"measurement","value":25,"unit":"mm","operator":null,"context":"s more than 2438 mm (8 feet), 25 mm (1 inch) of encroachment is p"},{"parameter":"measurement","value":1,"unit":"in","operator":null,"context":"than 2438 mm (8 feet), 25 mm (1 inch) of encroachment is permitt"},{"parameter":"measurement","value":25,"unit":"mm","operator":null,"context":"permitted for each additional 25 mm (1 inch) of clearance above 2"},{"parameter":"measurement","value":1,"unit":"in","operator":null,"context":"ed for each additional 25 mm (1 inch) of clearance above 2438 mm"},{"parameter":"measurement","value":2438,"unit":"mm","operator":null,"context":"m (1 inch) of clearance above 2438 mm (8 feet), but the maximum enc"},{"parameter":"measurement","value":8,"unit":"feet","operator":null,"context":") of clearance above 2438 mm (8 feet), but the maximum encroachmen"},{"parameter":"measurement","value":1219,"unit":"mm","operator":null,"context":"maximum encroachment shall be 1219 mm (4 feet)."},{"parameter":"measurement","value":4,"unit":"feet","operator":null,"context":"ncroachment shall be 1219 mm (4 feet)."}]','[]',0.93,'extracted','VERIFIED','2018','fba719b7a89325911748bcaa0b0e93af04f8fa15202dbae1a2c84f448c01ee66','2026-08-15 13:56:14'),
