INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-25581','GHBC-REQ-025581','GS 1207:2018',34,NULL,'34.6.4','GHBC-C-006702','Wood structural use panels 15.9 mm (5/8 inch) or thicker shall not span over 2438 mm (8 feet).','prohibited',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":15.9,"unit":"mm","operator":null,"context":"Wood structural use panels 15.9 mm (5/8 inch) or thicker shall n"},{"parameter":"measurement","value":8,"unit":"in","operator":null,"context":"uctural use panels 15.9 mm (5/8 inch) or thicker shall not span "},{"parameter":"measurement","value":2438,"unit":"mm","operator":null,"context":"r thicker shall not span over 2438 mm (8 feet)."},{"parameter":"measurement","value":8,"unit":"feet","operator":null,"context":" shall not span over 2438 mm (8 feet)."}]','[]',0.93,'requires_review','DRAFT','2018','69ae7c884d596e50ec0e88b8bd0bdc66d06253665ab36891b49743757398d403','2026-08-15 13:56:14'),
('rowid-25582','GHBC-REQ-025582','GS 1207:2018',34,NULL,'34.6.7','GHBC-C-006703','Covered walkways shall have a clear height of not less than 2438 mm (8 feet) as measured from the floor surface to the canopy overhead.','mandatory',NULL,NULL,NULL,NULL,'[" Roofs and supporting structures of covered walkways for new, light-frame construction not exceeding two stories above grade plane are permitted to be designed for a live load of 75 psf (3.6kN/m2) or the loads imposed on them, whichever is greater. In lieu of such designs, the roof and supporting structure of a covered walkway are permitted to be constructed as follows: 1. Footings shall be continuous 51 mm by 152 mm (2-inch by 6-inch) members. 2. Posts not less than 102 mm by 152 mm (4 inches by 6 inches) shall be provided on both sides of the roof and spaced not more than 3658 mm (12 feet) on center. 3. Stringers not less than 102 mm by 305 mm (4 inches by 12 inches) shall be placed on edge upon the posts. 4. Joists resting on the stringers shall be not less than 51 mm by 203 mm (2 inches by 8 inches) and shall be spaced not more than 610 mm (2 feet) on center. 5. The deck shall be planks not less than 51 mm (2 inches) thick or wood structural panels with an exterior exposure durability classification not less than 18.3 mm (23/ inch) thick nailed to the joists. 6. Each post shall be knee braced to joists and stringers by members not less than 51 mm by 102 mm (2 inches by 4 inches); 1219 mm (4 feet) in length."]','[{"parameter":"comparison","value":2438,"unit":null,"operator":"not less than","context":" shall have a clear height of not less than 2438 mm (8 feet) as measured from "},{"parameter":"measurement","value":2438,"unit":"mm","operator":null,"context":"clear height of not less than 2438 mm (8 feet) as measured from the"},{"parameter":"measurement","value":8,"unit":"feet","operator":null,"context":"ght of not less than 2438 mm (8 feet) as measured from the floor s"}]','[]',0.93,'extracted','VERIFIED','2018','708baddf979a8062a311b44fce26f4b7d90bdf222984db4e05653fb1b855073f','2026-08-15 13:56:14'),
