INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-25601','GHBC-REQ-025601','GS 1207:2018',34,'34.8','34.8.1.1','GHBC-C-006708','Construction materials and equipment shall not be placed or stored so as to obstruct access to fire hydrants, standpipes, fire or police alarm boxes, catch basins or manholes, nor shall such material or equipment be located within 6096 mm (20 feet) of a street inter- clause, or placed so as to obstruct normal observations of traffic signals or to hinder the use of public transit loading platforms.','prohibited',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":6096,"unit":"mm","operator":null,"context":"r equipment be located within 6096 mm (20 feet) of a street inter- "},{"parameter":"measurement","value":20,"unit":"feet","operator":null,"context":"nt be located within 6096 mm (20 feet) of a street inter- clause, o"}]','[]',0.93,'requires_review','DRAFT','2018','3a773530f5cc53b7a05e4969ab0d342d5defd028c6baf81ef1ad35960f180ef3','2026-08-15 13:56:14'),
('rowid-25602','GHBC-REQ-025602','GS 1207:2018',34,'34.8','34.8.2','GHBC-C-006709','Building materials, fences, sheds or any obstruction of any kind shall not be placed so as to obstruct free approach to any fire hydrant, fire department connection, utility pole, manhole, fire alarm box or catch basin, or so as to interfere with the passage of water in the gutter.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','b4aef808993f97925d128c7c4aff60056c7b29d3fec02b4b750d68de1eca7366','2026-08-15 13:56:14'),
('rowid-25603','GHBC-REQ-025603','GS 1207:2018',34,'34.8','34.8.2','GHBC-C-006709','Protection against damage shall be provided to such utility fixtures during the progress of the work, but sight of them shall not be obstructed.','prohibited',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'requires_review','DRAFT','2018','e1e789a3d26be6aa3d03b9b9e040de8793242c45acd997518a9761b33ccc1817','2026-08-15 13:56:14'),
('rowid-25604','GHBC-REQ-025604','GS 1207:2018',34,'34.9','34.9.1','GHBC-C-006710','Structures under construction, alteration or demolition shall be provided with not fewer than one approved portable fire extinguisher in accordance with this Code and sized for not less than ordinary hazard as follows: 1.','fire',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','31a166eb22baedf2753f3d23d81864cafc8f1b8db57e6d078eeaf2bcf1b818ac','2026-08-15 13:56:14'),
('rowid-25605','GHBC-REQ-025605','GS 1207:2018',34,'34.9','34.9.1','GHBC-C-006710','At each stairway on all floor levels where combustible materials have accumulated.','fire',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','776741aca8caae173208a8a6e117501837ceedc7f64d2c1c974e727f52397f1a','2026-08-15 13:56:14'),
